CREATE TABLE IF NOT EXISTS marketplace_publishers(id BIGSERIAL PRIMARY KEY,publisher_key VARCHAR(190) NOT NULL UNIQUE,name TEXT NOT NULL,public_key TEXT NOT NULL,trust_status VARCHAR(20) NOT NULL DEFAULT 'untrusted' CHECK(trust_status IN('trusted','untrusted','revoked')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketplace_packages(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64) NOT NULL,publisher_id BIGINT REFERENCES marketplace_publishers(id) ON DELETE SET NULL,package_type VARCHAR(40) NOT NULL,catalog_meta_json TEXT NOT NULL DEFAULT '{}',checksum VARCHAR(128) NOT NULL,signature TEXT NOT NULL DEFAULT '',license_product_key VARCHAR(190) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked','hidden')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version));
CREATE TABLE IF NOT EXISTS marketplace_entitlements(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,subject_type VARCHAR(40) NOT NULL,subject_value VARCHAR(255) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','expired','revoked')),expires_at TIMESTAMP,source VARCHAR(40) NOT NULL DEFAULT 'local',metadata_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,subject_type,subject_value));
CREATE TABLE IF NOT EXISTS marketplace_provenance(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64) NOT NULL,publisher_key VARCHAR(190),checksum VARCHAR(128) NOT NULL,signature_status VARCHAR(40) NOT NULL,license_status VARCHAR(40) NOT NULL,action VARCHAR(80) NOT NULL,actor_id BIGINT REFERENCES users(id) ON DELETE SET NULL,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketplace_revocations(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64),publisher_key VARCHAR(190),reason TEXT NOT NULL,revoked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version,publisher_key));
